export interface ProjectConfig {
  project?: string;
  manifestVersion?: 1 | 2 | 3;
  modeling?: { mode?: 'dbt-first' };
  layout?: { version?: number; mode?: string; skillsPath?: string };
  defaultConnection?: ConnectionConfig;
  defaultConnectionName?: string;
  connections?: Record<string, ConnectionConfig & { path?: string; type?: string }>;
  dataDir?: string;
  semanticLayer?: SemanticLayerProviderConfig;
  dbt?: {
    projectDir?: string;
    manifestPath?: string;
    profilesDir?: string;
    repoUrl?: string;
    branch?: string;
    subPath?: string;
  };
  preview?: {
    port?: number;
    theme?: string;
    open?: boolean;
  };
  notebook?: {
    staging?: {
      maxRows?: number;
      maxBytes?: number;
      timeoutSeconds?: number;
      expiryDays?: number;
    };
  };
  agent?: {
    runtimeValueGrounding?: {
      /** Runtime value lookup is opt-in because query literals may be sensitive. */
      mode?: 'disabled' | 'safe_automatic';
      /** Fully-qualified `schema.table.column` names approved by a project admin. */
      searchSafeColumns?: string[];
    };
    /**
     * How many executed rows may reach the AI provider when it writes the answer.
     * Defaults to a bounded, redacted sample: a model that cannot see the values
     * cannot describe them, and the fallback for that is a `column: value` dump.
     * Set `mode: 'disabled'` to keep every cell value on the host — narration
     * still runs, grounded in column names and computed statistics only.
     */
    providerResultRowEgress?: {
      mode?: 'bounded_sample' | 'disabled';
      /** Clamped to 0..20. Zero is treated as the kill-switch. */
      maxNarrationRows?: number;
    };
    /**
     * Which orchestrator answers a turn, migrated one lane at a time.
     *
     * `legacy` (the default) is the 10k-line answer loop. `agentic` routes the
     * listed lanes through the new loop with the old one as fallback. `shadow`
     * runs the new path for comparison only and never serves its answer.
     *
     * Defaults to legacy with no lanes on purpose: a flag that defaults on is
     * not a migration control, it is a release.
     */
    orchestrator?: {
      mode?: 'legacy' | 'shadow' | 'agentic';
      lanes?: string[];
      maxIterations?: number;
      fallbackOnError?: boolean;
    };
  };
  metadataScopes?: Record<string, ConnectionMetadataScopeInput>;
  /** Optional `dql propose` conventions (classifier + bounded selection). */
  propose?: ProposeConfigInput;
}

export function resolveProjectSemanticConfig(
  projectConfig: ProjectConfig,
  projectRoot: string,
): SemanticLayerProviderConfig | undefined {
  const configured = projectConfig.semanticLayer;
  const dbtProjectDir = projectConfig.dbt?.projectDir;
  const dbtManifestPath = projectConfig.dbt?.manifestPath;
  if (configured?.provider === 'dbt') {
    return {
      ...configured,
      projectPath: configured.projectPath ?? dbtProjectDir,
      manifestPath: configured.manifestPath ?? dbtManifestPath,
    };
  }
  if (
    dbtProjectDir
    && (!configured || configured.provider === 'dql')
    && hasDbtSemanticArtifacts(projectRoot, dbtProjectDir, dbtManifestPath)
  ) {
    return { provider: 'dbt', projectPath: dbtProjectDir, manifestPath: dbtManifestPath };
  }
  return configured;
}

function hasDbtSemanticArtifacts(projectRoot: string, dbtProjectDir: string, configuredManifestPath?: string): boolean {
  const dbtRoot = resolve(projectRoot, dbtProjectDir);
  const manifestPath = resolve(dbtRoot, configuredManifestPath ?? 'target/manifest.json');
  if (existsSync(join(dirname(manifestPath), 'semantic_manifest.json'))) return true;
  if (!existsSync(manifestPath)) return false;
  try {
    const parsed = JSON.parse(readFileSync(manifestPath, 'utf-8')) as Record<string, unknown>;
    if (parsed.semantic_models && typeof parsed.semantic_models === 'object') return true;
    if (parsed.metrics && typeof parsed.metrics === 'object') return true;
  } catch {
    return false;
  }
  return false;
}

