export interface LocalServerOptions {
  rootDir: string;
  projectRoot?: string;
  executor: QueryExecutor;
  connection?: ConnectionConfig | null;
  preferredPort: number;
  /**
   * Host the HTTP server binds to. Defaults to `127.0.0.1` (loopback only)
   * for security. Set to `0.0.0.0` when running inside a container so the
   * port is reachable from the host. Honours `DQL_HOST` env var when unset.
   */
  host?: string;
  /** Required for non-loopback bindings. Defaults to `DQL_SERVER_TOKEN`. */
  authToken?: string;
  /** Exact browser origins allowed for non-loopback API access. */
  allowedOrigins?: string[];
  /**
   * Receives the underlying HTTP server once created, so short-lived callers
   * (e.g. `dql agent ask` starting an ephemeral runtime) can `close()` it and
   * let the process exit instead of hanging on an open listener.
   */
  captureServer?: (server: import('node:http').Server) => void;
  /**
   * Test/embedding seam for deterministic agent-run execution without a live LLM.
   * Production callers leave this unset and use the default governed executors.
  */
  agentRunExecutors?: AgentRunExecutors;
  /** Host-owned rollback seam; never read from client request payloads. */
  requireMeaningCallForNaturalLanguage?: boolean;
}

// Every member of `AgentRunRequestedMode`. The `Record` (rather than a bare
// Set literal) is deliberate: a `Set<AgentRunRequestedMode>` happily accepts a
// subset, which is how 'modeling' and 'skill' went missing here — the parser
// dropped them to `undefined`, `selectRoute` never saw an explicit mode, and
// Modeling AI silently ran the governed answer loop instead of proposing a
// model. A Record makes an omission a compile error.
const AGENT_RUN_REQUESTED_MODE_MEMBERS: Record<AgentRunRequestedMode, true> = {
  auto: true, ask: true, research: true, sql: true, block: true, app: true, modeling: true, skill: true,
};
const AGENT_RUN_REQUESTED_MODES = new Set<AgentRunRequestedMode>(
  Object.keys(AGENT_RUN_REQUESTED_MODE_MEMBERS) as AgentRunRequestedMode[],
);

